-- 165_replace_decision_320_2025_license_amendment_to_microinsurance_rules_polluted_with_reversed_ligatures_kashida_junk_and_page_headers_with_preamble_and_6_articles.sql
--
-- إعادة رفع قرار مجلس إدارة الهيئة العامة للرقابة المالية رقم (320) لسنة 2025 بشأن ضوابط وإجراءات تعديل ترخيص الشركات التى تزاول نشاط تأمين الأشخاص وتكوين الأموال أو نشاط تأمينات الممتلكات والمسئوليات لمزاولة نشاط التأمين متناهى الصغر،
-- المنشور بالوقائع المصرية، العدد 29، فى 5 فبراير 2026 (الصفحات 18 إلى 23): ديباجة وست مواد، بلا قواعد مرفقة (فمفاتيح المواد كلها article_suffix_order = 0).
--
-- ===== الحالة السابقة (مراجعة الـ153 وثيقة، أولوية P1) =====
-- مخزَّن بالبذور (6 صفوف، 6594 حرفاً) مأخوذ من طبقة النص فى PDF دون تنظيف، وبه:
-- (1) حروف اللام ألف مقلوبة الترتيب فى الصفوف الستة كلها ("األشخاص" و"اإلجراءات" و"أعاله" و"خالل ثالثين" ...)، وبقايا تطويل تالفة (U+FFFD، 273 حرفاً فى الصفوف الستة) تتخلل الكلمات ("يعم���ل" و"أح���كام")؛
-- (2) ترويسة صفحات الوقائع ("الوقائع املصرية - العدد 29فى 5فبراير سنة 2026" ورقم الصفحة) داخل خمسة صفوف (1 و2 و3 و5 و6) وفاصل صفحة؛
-- (3) أرقام هندية فى ثلاثة صفوف (12 حرفاً)، وأرقام البنود مقلوبة الموضع ("- 1الحصول" و"-٢إعداد")، وتنوين مفصول عن حرفه ("ً والقرارات" و"ً يوما") فى ثلاثة صفوف، و98 فاصل CRLF داخل الجمل؛
-- (4) بلا ديباجة ولا عناوين مواد ولا تاريخ سريان، فلا يعرف القارئ أن الاطلاعات والموافقة على القرار سابقة لأحكامه؛
-- (5) شظايا مبعثرة الترتيب فى نهايات المواد (المادة 2 تنتهى بـ"ً والقرارات الصادرة"، والمادة 5 بـ"خالل ثالثين ً يوما على األكثر") والتوقيع فى المادة 6 بصيغة "د .محمد فريد صالح".
-- فلا يصلح النص المخزَّن للاستشهاد الرسمى ولا لإدخاله إلى سياق نموذج اللغة.
--
-- ===== المصدر والمنهجية =====
-- PDF الوقائع المصرية (6 صفحات، 381.6 كيلوبايت) قدّمه صاحب المشروع؛ بلا علامة مائية، وجدول مراجعه تالف أُصلح بـqpdf قبل الاستخراج. استُخرج النص من مواضع الحروف نفسها (pdfplumber) لا من مخرجات poppler التى تقلب اللام ألف وتُخرج رموز التطويل تالفة،
-- ثم رُتّبت الحروف منطقياً (مقاطع الأرقام واللاتينية تُترك كما هى، ومقاطع العربية تُعكس)، وأُعيد تركيب الفقرات والبنود والبنود الفرعية بإحداثيات الأسطر (بداية الفقرة أو البند سطر مُزاح عن الهامش الأيمن بمقدار ثابت فى كل صفحات الملف).
-- حُذفت ترويسة الصفحات وأرقام الصفحات وسطر جهة الإصدار "مجلس إدارة الهيئة العامة للرقابة المالية"؛ وعنوان القرار وبيان نشره بالوقائع فى hierarchical_location للديباجة. التوقيع باقٍ فى المادة 6. المواد بلا عناوين فى الأصل فعنوانها "المادة الأولى" وهكذا.
-- أُبقيت كتابة الأصل وأخطاؤه كما طُبعت ("تقدم الشركة طلب للهيئة" بالمادة 3 و"ما يلي" و"المصري" و"متناهي الصغر" بالياء)؛ لم يُعدَّل لفظ واحد. الأرقام لاتينية والتنوين فى موضعه كما طُبع (فصار "وفقًا" و"تنفيذًا" و"طلبًا" و"يومًا")،
-- وأُسقطت الضمة وغيرها من علامات التشكيل الصغيرة والتطويل، وضُبطت المسافات حول الفاصلة والنقطتين والفاصلة المنقوطة (" ، " و" : " و" ؛ ") وأُضيفت مسافة بين الرقم أو القوس والكلمة الملتصقة به؛ وُحِّدت مسافات التنوين المزدوجة.
-- قوبل النص المُدخَل بمخرجات OCR مستقلة (tesseract ara) على صور الصفحات الست: لم يبق فرق فى ألفاظ غير ضجيج التعرف على الحروف والأرقام والعناوين، ولا فرق حقيقى فى كلمة واحدة.
--
-- ===== الهيكل =====
-- 7 صفوف، 7 نسخ (version_no = 1): ديباجة (article_no = 0) بالاطلاعات الخمسة (القانون 10 لسنة 2009، وقانون التأمين الموحد 155 لسنة 2024 والقرارات الصادرة تنفيذاً له، والقرارات 177 لسنة 2024 و15 لسنة 2025 و319 لسنة 2025) وموافقة مجلس الإدارة بجلسته بتاريخ 2025/12/24؛
-- ثم المواد 1 إلى 6 بأرقامها الأصلية وعناوينها ("المادة الأولى" ...؛ بلا عنوان موضوعى كما فى الأصل). مفاتيح المواد هى المخزَّنة نفسها (1..6، 0) فلا تعيد البذور إدراج القديم.
--
-- ===== التاريخ =====
-- effective_from = 2026-02-06: المادة 6 تعمل بالقرار "من اليوم التالى لتاريخ نشره بالوقائع المصرية"، ونشره بالعدد 29 بتاريخ 2026/2/5 (ثابت بترويسة كل صفحة). كان القديم تاريخ تشغيل البذر لا تاريخ سريان.
--
-- ===== قابلية إعادة التشغيل =====
-- الحذف مشروط بألا تكون الحالة نظيفة (7 صفوف بديباجة سليمة والمادة 6 موجودة)؛ والإدراج ON CONFLICT DO NOTHING. تحقق الختام محصور فى هذا القرار ويفشل عند أى انحراف (عدد، أو ترويسة، أو بقايا تلف،
-- أو محتوى المواد، أو إجمالى الطول 6544 حرفاً).
--
-- ملاحظة تشغيلية: المواد الجديدة بلا embedding؛ يلزم scripts/backfill-embeddings.js بعد النشر.

BEGIN;
DO $fix165$
DECLARE
  v_law_id uuid;
  v_n int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 320 AND law_year = 2025 AND kind = 'board_decision';
  IF v_law_id IS NULL THEN
    RAISE WARNING '[165] القرار 320/2025 غير موجود فى laws — تخطّى';
    RETURN;
  END IF;
  IF (SELECT count(*) FROM articles WHERE law_id = v_law_id) = 7
     AND EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 0 AND article_suffix_order = 0 AND title = 'ديباجة القرار' AND body LIKE 'بعد الاطلاع%')
     AND EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 6 AND article_suffix_order = 0) THEN
    RAISE NOTICE '[165] القرار 320/2025 نظيف بالفعل — تخطّى الحذف';
  ELSE
    SELECT count(*) INTO v_n FROM articles WHERE law_id = v_law_id;
    DELETE FROM articles WHERE law_id = v_law_id;
    RAISE NOTICE '[165] أُزيلت % مادة من القرار 320/2025 (نص مخزَّن ملوَّث بحروف مقلوبة ورموز تطويل تالفة وترويسات صفحات، وبلا ديباجة ولا عناوين ولا تاريخ سريان)', v_n;
  END IF;
END
$fix165$;

WITH ins0_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 0, 0, $h0$قرار مجلس إدارة الهيئة العامة للرقابة المالية رقم 320 لسنة 2025 (منشور بالوقائع المصرية العدد 29 فى 2026/2/5) بشأن ضوابط وإجراءات تعديل ترخيص الشركات التى تزاول نشاط تأمين الأشخاص وتكوين الأموال أو نشاط تأمينات الممتلكات والمسئوليات لمزاولة نشاط التأمين متناهى الصغر$h0$, $t0_0$ديباجة القرار$t0_0$, $b0_0$بعد الاطلاع على القانون رقم 10 لسنة 2009 بتنظيم الرقابة على الأسواق والأدوات المالية غير المصرفية ؛
وعلى قانون التأمين الموحد الصادر بالقانون رقم 155 لسنة 2024 والقرارات الصادرة تنفيذًا له ؛
وعلى قرار مجلس إدارة الهيئة رقم 177 لسنة 2024 بشأن ضوابط منح الترخيص واستمراره للشركات العاملة فى الأنشطة المالية غير المصرفية ؛
وعلى قرار مجلس إدارة الهيئة رقم 15 لسنة 2025 بشأن قواعد تأسيس وترخيص الشركات العاملة فى نشاط التأمين وإعادة التأمين ؛
وعلى قرار مجلس إدارة الهيئة رقم 319 لسنة 2025 بشأن الشروط والقواعد الحاكمة لنشاط التأمين متناهي الصغر ؛
وبعد موافقة مجلس إدارة الهيئة بجلسته المنعقدة بتاريخ 2025/12/24 ؛$b0_0$
  FROM laws WHERE law_no = 320 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-02-06', 'active' FROM ins0_0;

WITH ins1_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 1, 0, NULL, $t1_0$المادة الأولى$t1_0$, $b1_0$يعمل بأحكام هذا القرار فى شأن ضوابط وإجراءات تعديل ترخيص الشركات التى تزاول نشاط تأمين الأشخاص وتكوين الأموال أو نشاط تأمينات الممتلكات والمسئوليات لمزاولة نشاط التأمين متناهى الصغر فى سوق التأمين المصري.$b1_0$
  FROM laws WHERE law_no = 320 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-02-06', 'active' FROM ins1_0;

WITH ins2_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 2, 0, NULL, $t2_0$المادة الثانية$t2_0$, $b2_0$تلتزم الشركات المشار إليها بالمادة الأولى من هذا القرار باتباع الإجراءات الآتية حال رغبتها فى تعديل ترخيصها لمزاولة نشاط التأمين متناهى الصغر :
1- الحصول على موافقة مبدئية من الجمعية العامة العادية للشركة على تعديل الترخيص ، وحال كون الشركة تعمل بنظام التأمين التكافلى يشترط موافقة لجنة الرقابة الشرعية.
2- إعداد تقارير فحص نافى للجهالة (مالى وفنى وقانونى وضريبي) لتحديد حقوق والتزامات الشركة ومساهميها وحملة الوثائق فى تاريخ تعديل الترخيص ، على أن يتم اعتماد تلك التقارير من المستشارين المتخصصين فى المسائل المالية والفنية والقانونية والضريبية كل فيما يخصه وكذا من مجلس إدارة الشركة.
3- معالجة حالة وثائق التأمين القائمة لدى الشركة وغير المتوافقة مع أنواع وفروع التأمين المطلوب تعديل الترخيص لمزاولتها ، على أن تتضمن تلك المعالجة الأسس القانونية والفنية والمحاسبية والاكتوارية فى التصرف فى تلك الوثائق من خلال أى من الإجراءات الآتية :
(أ) إبراء ذمة الشركة بشكل كلى ونهائى من التزاماتها عن جميع الوثائق القائمة فى تاريخ التعديل.
(ب) تحويل تلك الوثائق لشركة تأمين أخرى مرخص لها بمزاولة النشاط.
(ج) استمرار سريان تلك الوثائق مع التعهد بتصفيتها خلال فترة لا تجاوز سنة من تاريخ تعديل الترخيص ، على أن يتم فصل حسابات تلك الوثائق فى حسابات مستقلة وفقًا للقواعد المعمول بها فى هذا الشأن خلال المدة المذكورة.
4- إعداد خطة بشأن إقفال أية خسائر مرحلة للشركة (حال وجودها) بحقوق الملكية وذلك فى تاريخ التعديل ، وذلك مع الالتزام بأحكام قانون التأمين الموحد والقرارات الصادرة تنفيذًا له بالنسبة للحد الأدنى ومدى كفاية رأس المال المخاطر.$b2_0$
  FROM laws WHERE law_no = 320 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-02-06', 'active' FROM ins2_0;

WITH ins3_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 3, 0, NULL, $t3_0$المادة الثالثة$t3_0$, $b3_0$تقدم الشركة طلب للهيئة للحصول على عدم ممانعة مجلس إدارة الهيئة على العرض على الجمعية العامة غير العادية للشركة لتعديل الترخيص ، على أن يرفق بالطلب المستندات الآتية :
1- محضر اجتماع الجمعية العامة للشركة وموافقة لجنة الرقابة الشرعية - بحسب الأحوال - على النحو المشار إليه بالبند (1) من المادة الثانية من هذا القرار.
2- تقارير الفحص النافى للجهالة المشار إليها بالبند (2) من المادة الثانية من هذا القرار.
3- طريقة معالجة حالة وثائق التأمين القائمة لدى الشركة وغير المتوافقة مع أنواع وفروع التأمين المطلوب تعديل الترخيص لمزاولتها على النحو المشار إليه بالبند (3) من المادة الثانية من هذا القرار.
4- الخطة المشار إليها بالبند (4) من المادة الثانية من هذا القرار.
5- ما يفيد النشر فى صحفيتين يوميتين واسعة الانتشار فى مكان ظاهر وكذا على الموقع الإلكترونى للشركة ، باعتزام الشركة تعديل ترخيص لمزاولة نشاط التأمين متناهى الصغر ، على أن يتضمن النشر دعوة حملة الوثائق والمستفيدين منها وغيرهم من ذوى الشأن إلى تقديم اعتراضاتهم إلى الهيئة فى موعد غايته شهر من تاريخ النشر على أن يبين بالاعتراض الأسانيد المؤيدة له.
6- دراسة الجدوى الفنية والاقتصادية للشركة وفروع التأمين المزمع القيام بمزاولتها وخطة عمل الشركة خلال السنوات الخمس الأولى من تاريخ تعديل الترخيص ، مع توضيح تقديرات الأقساط والمصروفات وتكاليف الإنتاج والأسس الفنية التى بنيت عليه ، وذلك وفقًا للنموذج المعد من الهيئة لهذا الغرض وعلى أن تتضمن بحد أدنى ما يلي :
(أ) الجدوى الفنية والاقتصادية للنشاط المطلوب مزاولته ورؤية الشركة نحو تنمية سوق التأمين سواء بإضافة منتجات جديدة أو التطوير على المنتجات القائمة أو إضافة آليات تسويق غير تقليدية أو التوسع فى مناطق جديدة وآليات استخدام التكنولوجيا فى العمليات التشغيلية للشركة ، وخطة عمل فنية خاصة بأعمال التشغيل والمراجعة وتسويق المنتجات التأمينية للشركة.
(ب) الهدف والاستراتيجية والسياسة المزمع اتباعها فى تصريف أمور الشركة.
(ج) أوجه الرقابة الداخلية والحوكمة والاستثمار.
(د) خطة التدريب والتطوير للعاملين بالشركة.
7- نسخة من الهيكل التنظيمى المعدل للشركة ، إذا ما اقتضى الأمر ذلك.$b3_0$
  FROM laws WHERE law_no = 320 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-02-06', 'active' FROM ins3_0;

WITH ins4_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 4, 0, NULL, $t4_0$المادة الرابعة$t4_0$, $b4_0$تتولى الهيئة دراسة طلب الشركة المشار إليه بالمادة السابقة وأى اعتراضات ترد لها فى هذا الشأن ، ولها طلب استيفاء أى بيانات أو مستندات ترى ضرورة تقديمها للبت فى الطلب ، ويجوز لها إجراء الفحص الميدانى للشركة للتحقق من استيفاء المتطلبات اللازمة لمزاولة النشاط ، كما يجوز لها تعيين أحد الخبراء المتخصصين للتحقق من أى من البنود المشار إليها أعلاه على أن تتحمل تكاليفه الشركة الراغبة فى تعديل ترخيصها. ويتم إعداد تقرير فى هذا الشأن للعرض على مجلس إدارة الهيئة للنظر فى إصدار قرار بعدم ممانعته على تعديل الترخيص.$b4_0$
  FROM laws WHERE law_no = 320 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-02-06', 'active' FROM ins4_0;

WITH ins5_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 5, 0, NULL, $t5_0$المادة الخامسة$t5_0$, $b5_0$تقوم الشركة بعد الحصول على عدم ممانعة مجلس إدارة الهيئة على تعديل الترخيص وبعد استيفاء متطلبات الهيئة على النحو المشار إليه بهذا القرار ، بالدعوة للجمعية العامة غير العادية للشركة للنظر فى الموافقة على تعديل اسم الشركة وغرضها بما يتوافق مع نشاط التأمين متناهى الصغر ، والتوافق مع متطلبات رأس المال وهيكل الملكية وفقًا لقانون التأمين الموحد وقرارات مجلس إدارة الهيئة الصادرة فى هذا الشأن إذا اقتضى الأمر ذلك.
وتقدم الشركة - بعد موافقة الجمعية العامة غير العادية - طلبًا للهيئة لاستكمال إجراءات تعديل الترخيص مرفقًا به ما يلي :
1- محضر اجتماع الجمعية العامة للشركة على النحو المشار إليه بهذه المادة.
2- نماذج الوثائق التى تصدرها الشركة بنظام التأمين متناهى الصغر عن كل فرع من فروع التأمين المطلوب الترخيص بمزاولتها ومزايا وقيود وشروط وأسعار تلك الوثائق.
3- ما يفيد قيام الشركة بإقفال أية خسائر مرحلة فى حقوق الملكية مع الالتزام بأحكام قانون التأمين الموحد والقرارات الصادرة تنفيذًا له بالنسبة للحد الأدنى ومدى كفاية رأس المال المخاطر.
4- ترتيبات إعادة التأمين وفقًا للنشاط المطلوب تعديل الترخيص لمزاولته ، ويجب أن تكون هذه الترتيبات كافية لحماية حقوق حملة الوثائق وسلامة المركز المالى للشركة ، ويجب أن تتضمن المستندات التى تقدم فى هذا الشأن بيان توزيع حصص معيدى التأمين وملخصًا وافيًا لها.
5- بيان بأسماء مساهمى الشركة وحصة كل منهم وجنسياتهم وخبرتهم السابقة ونسبة مساهماتهم فى أى شركة تأمين أخرى مرخص لها بمزاولة النشاط سواء بشكل مباشر أو غير مباشر.
6- البيانات الخاصة بأعضاء مجلس إدارة الشركة والقائمين على الإدارة التنفيذية بها.
7- نسخة من السجل التجارى والنظام الأساسى للشركة المعدل وفقًا للنموذج المعد لذلك من الهيئة فى هذا الشأن.
وتتولى الهيئة دراسة طلب الشركة المشار إليه ، ولها طلب استيفاء أى بيانات أو مستندات ترى ضرورة تقديمها للبت فى الطلب ، وتصدر الهيئة قرارها فى طلب الشركة خلال ثلاثين يومًا على الأكثر من تاريخ تقديم المستندات مستوفاة.$b5_0$
