DO $verify165$
DECLARE
  v_law_id uuid;
  v_n int; v_v int; v_bad int; v_len int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 320 AND law_year = 2025 AND kind = 'board_decision';
  IF v_law_id IS NULL THEN
    RAISE WARNING '[165] القرار 320/2025 غير موجود — لا تحقق';
    RETURN;
  END IF;
  SELECT count(*), COALESCE(sum(length(body)), 0) INTO v_n, v_len FROM articles WHERE law_id = v_law_id;
  IF v_n <> 7 THEN RAISE EXCEPTION '[165] عدد المواد % بدل 7', v_n; END IF;
  SELECT count(*) INTO v_v FROM article_versions av JOIN articles a ON a.id = av.article_id WHERE a.law_id = v_law_id AND av.version_no = 1 AND av.status = 'active' AND av.effective_from = DATE '2026-02-06';
  IF v_v <> 7 THEN RAISE EXCEPTION '[165] عدد النسخ % بدل 7', v_v; END IF;
  SELECT count(*) INTO v_bad FROM articles WHERE law_id = v_law_id AND (body ~ '[٠-٩۰-۹]' OR body ~ '[ٌ-ْ]' OR body LIKE '%' || chr(65533) || '%' OR body LIKE '%ـ%' OR body LIKE '%األ%' OR body LIKE '%اإل%' OR body LIKE '%اآل%' OR body LIKE '%خالل%' OR body LIKE '%أعاله%' OR body LIKE '%الوقائع املصرية%' OR body LIKE '%العدد 29%' OR body LIKE '%فبراير سنة 2026%' OR body LIKE '% ً%' OR body LIKE '%���%');
  IF v_bad > 0 THEN RAISE EXCEPTION '[165] % مادة بها تلف أو بقايا OCR أو ترويسة', v_bad; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 0 AND article_suffix_order = 0 AND body LIKE 'بعد الاطلاع على القانون رقم 10 لسنة 2009 بتنظ%' AND body LIKE '%ه المنعقدة بتاريخ 2025/12/24 ؛' AND body LIKE '%رقم 10 لسنة 2009%' AND body LIKE '%رقم 155 لسنة 2024%' AND body LIKE '%رقم 177 لسنة 2024%' AND body LIKE '%رقم 15 لسنة 2025%' AND body LIKE '%رقم 319 لسنة 2025%' AND body LIKE '%بتاريخ 2025/12/24 ؛%') THEN RAISE EXCEPTION '[165] ديباجة غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 1 AND article_suffix_order = 0 AND body LIKE 'يعمل بأحكام هذا القرار فى شأن ضوابط وإجراءات%' AND body LIKE '%ى الصغر فى سوق التأمين المصري.' AND body LIKE '%فى سوق التأمين المصري.%') THEN RAISE EXCEPTION '[165] المادة 1 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 2 AND article_suffix_order = 0 AND body LIKE 'تلتزم الشركات المشار إليها بالمادة الأولى من%' AND body LIKE '%ومدى كفاية رأس المال المخاطر.' AND body LIKE '%1- الحصول على موافقة مبدئية%' AND body LIKE '%(ج) استمرار سريان%' AND body LIKE '%فترة لا تجاوز سنة%' AND body LIKE '%4- إعداد خطة%') THEN RAISE EXCEPTION '[165] المادة 2 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 3 AND article_suffix_order = 0 AND body LIKE 'تقدم الشركة طلب للهيئة للحصول على عدم ممانعة%' AND body LIKE '%شركة ، إذا ما اقتضى الأمر ذلك.' AND body LIKE '%(أ) الجدوى الفنية%' AND body LIKE '%فى موعد غايته شهر من تاريخ النشر%' AND body LIKE '%(د) خطة التدريب%' AND body LIKE '%7- نسخة من الهيكل التنظيمى المعدل%') THEN RAISE EXCEPTION '[165] المادة 3 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 4 AND article_suffix_order = 0 AND body LIKE 'تتولى الهيئة دراسة طلب الشركة المشار إليه بال%' AND body LIKE '%عدم ممانعته على تعديل الترخيص.' AND body LIKE '%للنظر فى إصدار قرار بعدم ممانعته على تعديل الترخيص.%') THEN RAISE EXCEPTION '[165] المادة 4 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 5 AND article_suffix_order = 0 AND body LIKE 'تقوم الشركة بعد الحصول على عدم ممانعة مجلس إد%' AND body LIKE '%تاريخ تقديم المستندات مستوفاة.' AND body LIKE '%مرفقًا به ما يلي :%' AND body LIKE '%7- نسخة من السجل التجارى%' AND body LIKE '%خلال ثلاثين يومًا على الأكثر%') THEN RAISE EXCEPTION '[165] المادة 5 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 6 AND article_suffix_order = 0 AND body LIKE 'ينشر هذا القرار فى الوقائع المصرية وعلى الموق%' AND body LIKE '%د. محمد فريد صالح' AND body LIKE '%ويعمل به من اليوم التالى لتاريخ نشره بالوقائع المصرية.%' AND body LIKE '%د. محمد فريد صالح') THEN RAISE EXCEPTION '[165] المادة 6 غير سليم'; END IF;
  IF v_len <> 6544 THEN RAISE EXCEPTION '[165] إجمالى طول المواد % بدل 6544', v_len; END IF;
  RAISE NOTICE '[165] القرار 320/2025: 7 مواد و7 نسخ، إجمالى % حرف', v_len;
END
$verify165$;

COMMIT;
